#!/usr/bin/env node
// Regenerates src/advisories/data.ts from the repository advisory database.
// Run from packages/core: `node scripts/bundle-advisories.mjs`.
// CI verifies the generated file is in sync (`git diff --exit-code`).
import fs from 'node:fs';
import path from 'node:path';
import url from 'node:url';

const here = path.dirname(url.fileURLToPath(import.meta.url));
const dbDir = path.resolve(here, '../../../advisories');
const outFile = path.resolve(here, '../src/advisories/data.ts');

const entries = fs
  .readdirSync(dbDir)
  .filter((f) => /^MCPA-\d{4}-\d{4}\.json$/.test(f))
  .sort()
  .map((f) => {
    const a = JSON.parse(fs.readFileSync(path.join(dbDir, f), 'utf8'));
    return {
      id: a.id,
      title: a.title,
      type: a.type,
      severity: a.severity,
      packages: a.packages.map((p) => ({
        ecosystem: p.ecosystem,
        name: p.name,
        ranges: p.ranges,
      })),
    };
  });

const banner = `// GENERATED by scripts/bundle-advisories.mjs from /advisories — do not edit by hand.
import { McpaAdvisory } from './types.js';

export const MCPA_ADVISORIES: McpaAdvisory[] = `;

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, `${banner}${JSON.stringify(entries, null, 2)};\n`);
console.log(`bundled ${entries.length} advisories → ${path.relative(process.cwd(), outFile)}`);
